parameters.text:
=✅ <b>Backup OK</b>
📅 <code>{{ $json.body?.date ?? '?' }}</code> · {{ $json.body?.tier ?? '?' }}

📦 {{ $json.body?.components ? $json.body.components.length + ' components' : '⚠️ invalid payload' }}
💾 {{ (($json.body?.total_size_bytes ?? 0)/1048576).toFixed(1) }} MB
{{ !$json.body?.storage ? '⚠️ Storage status missing' : $json.body.storage.age_days < 0 ? '⚠️ Storage never synced' : ($json.body.storage.status === 'ok' || $json.body.storage.age_days === 0) ? '🖼 Storage ' + ($json.body.storage.mirror_bytes/1048576).toFixed(0) + ' MB · today' : $json.body.storage.age_days > 8 ? '⚠️ Storage stale · ' + $json.body.storage.age_days + 'd ago' : '🖼 Storage ' + ($json.body.storage.mirror_bytes/1048576).toFixed(0) + ' MB · ' + $json.body.storage.age_days + 'd ago' }}

<blockquote expandable>{{ ($json.body?.components ?? []).map(c => c.name + ' · ' + (c.size >= 1048576 ? (c.size/1048576).toFixed(1) + ' MB' : c.size >= 1024 ? Math.round(c.size/1024) + ' KB' : c.size ? c.size + ' B' : c.status)).join('\n') || '—' }}</blockquote>
